         /* isry.drmgs.link.OfcdcLinkAplyMapper.insertOfcdcGrFileUld(교육청집단연계-파일업로드) */

          INSERT INTO AKA220 /* 교육청집단연계-파일업로드 */
            (MNG_SN
			, ENFSN_NO			
			, FRST_RGTR_ID
			, FRST_REG_DT
			, LAST_MDFR_ID
			, LAST_MDFCN_DT)
          VALUES(
              #{MNG_SN}
            , #{ENFSN_NO}                       
            , #{FRST_RGTR_ID} 
            , SYSDATE
            , #{LAST_MDFR_ID} 
            , SYSDATE
            )

         /* isry.drmgs.link.OfcdcLinkAplyMapper.insertOfcdcGrFileUldDtl(교육청집단연계-업로드파일상세) */

          INSERT INTO AKA221     /* 교육청집단연계-업로드파일상세 */
			(MNG_SN
			, ENFSN_NO
			, INDEX_SN
			, ULD_RQSTDO_STTS_SE_CD
			, STDNT_WRTCNS_SBMSN_YN
			, STTY_AGT_WRTCNS_SBMSN_YN
			, STDNT_FLNM_ENCPT
			, STDNT_BRTH_YMD
			, STDNT_SXDC_NM
			, STDNT_ADDR
			, STDNT_MBL_TELNO_ENCPT
			, STDNT_TELNO
			, STDNT_EML_ADDR_ENCPT
			, STTY_AGT_CTTPC_TELNO
			, STTY_AGT_EML_ADDR_ENCPT
			, LAST_SCHL_GRADE_NM
			, SCHULW_DSCNTC_YMD
			, SCHULW_DSCNTC_CS_CN
			, HNCFRT_HPE_COSE_NM
			, ERR_INFO_DTL_CN
			, FRST_RGTR_ID
			, FRST_REG_DT
			, LAST_MDFR_ID
			, LAST_MDFCN_DT)
			VALUES(
			  #{MNG_SN}
			, #{ENFSN_NO}
			, AKA221_SQ01.NEXTVAL
			, #{ULD_RQSTDO_STTS_SE_CD}
			, #{STDNT_WRTCNS_SBMSN_YN}
			, #{STTY_AGT_WRTCNS_SBMSN_YN}
			, (SELECT C##RG.ENC_B64(#{STDNT_FLNM_ENCPT}) FROM DUAL)
			, #{STDNT_BRTH_YMD}
			, #{STDNT_SXDC_NM}
			, #{STDNT_ADDR}
			, (SELECT C##RG.ENC_B64(#{STDNT_MBL_TELNO_ENCPT}) FROM DUAL)
			, #{STDNT_TELNO}
			, (SELECT C##RG.ENC_B64(#{STDNT_EML_ADDR_ENCPT}) FROM DUAL)
			, #{STTY_AGT_CTTPC_TELNO}
			, (SELECT C##RG.ENC_B64(#{STTY_AGT_EML_ADDR_ENCPT}) FROM DUAL)
			, #{LAST_SCHL_GRADE_NM}
			, #{SCHULW_DSCNTC_YMD}
			, #{SCHULW_DSCNTC_CS_CN}
			, #{HNCFRT_HPE_COSE_NM}
			, #{ERR_INFO_DTL_CN}
			, #{FRST_RGTR_ID} 
			, SYSDATE
			, #{LAST_MDFR_ID} 
			, SYSDATE
			)

