SELECT /* isry.drmgs.link.OfcdcLinkAplyMapper.selectDupChk(중복등록확인) */
       COUNT(1) AS sDupChk
 FROM AKA221     /* 교육청집단연계-업로드파일상세 */
WHERE 1=1
  AND ERR_INFO_DTL_CN IS NULL
  AND STDNT_FLNM_ENCPT      = (SELECT C##RG.ENC_B64(#{STDNT_FLNM_ENCPT}) FROM DUAL)
  AND STDNT_BRTH_YMD        = #{STDNT_BRTH_YMD}
  AND STDNT_SXDC_NM         = #{STDNT_SXDC_NM}


           AND STDNT_MBL_TELNO_ENCPT = (SELECT C##RG.ENC_B64(#{STDNT_MBL_TELNO_ENCPT}) FROM DUAL)




           AND STDNT_TELNO = #{STDNT_TELNO}

SELECT /* isry.drmgs.link.OfcdcLinkAplyMapper.selectLinkRqstList(연계의뢰서 업로드(집단) 조회) */ T1.MNG_SN AS MNG_SN ,T1.ENFSN_NO AS ENFSN_NO ,T1.TOT_NOCS AS TOTAL_NOCS ,T1.NEW_REG_NOCS AS NEW_REG_NOCS ,T1.DPCN_NOCS AS DPCN_NOCS ,T1.ERR_INFO_NOCS AS ERR_INFO_NOCS ,T1.SPCLA_MNG_NOCS AS SPCLA_MNG_NOCS ,T1.FAIL_NOCS AS FAIL_NOCS ,TO_CHAR(T1.ULD_DT,'YYYYMMDD HH24:MI:SS') AS ULD_DT ,C##RG.DEC_B64(T2.FLNM_ENCPT) AS PIC_FLNM ,T3.INST_NM AS OFCDC FROM AKA220 T1/* 교육청집단연계-파일업로드 */ ,SCA100 T2/* 종사자 */ ,SAA000 T3/* 통합기관 */ WHERE 1=1 AND T1.ENFSN_NO = T2.ENFSN_NO AND T2.OGDP_INST_NO = T3.INST_NO AND T1.ENFSN_NO = #{ENFSN_NO} AND TO_CHAR(T1.ULD_DT,'YYYYMMDD') BETWEEN #{START_DATE} AND #{END_DATE}
AND T2.FLNM_ENCPT = C##RG.ENC_B64(#{PIC_FLNM})
ORDER BY T1.ULD_DT DESC

mapper.update:

/* isry.drmgs.link.OfcdcLinkAplyMapper.updateLinkRqst(교육청집단연계(AKA220) update)  */

UPDATE AKA220 /* 교육청집단연계-파일업로드 */
   SET ULD_DT               = SYSDATE
     , TOT_NOCS             = #{sTot}
     , NEW_REG_NOCS         = #{sNewReg}
     , DPCN_NOCS            = #{sDpcn}
     , ERR_INFO_NOCS        = #{sErrInfo}
     , SPCLA_MNG_NOCS       = #{sSpcla}
     , FAIL_NOCS            = #{sFail}
     , LAST_MDFR_ID         = #{LAST_MDFR_ID}
     , LAST_MDFCN_DT        = SYSDATE
 WHERE MNG_SN               = #{MNG_SN}
   AND ENFSN_NO             = #{sEnfsnNo}

mapper.select:
SELECT /* isry.drmgs.link.OfcdcLinkAplyMapper.selectOfcdcSpclaMngList(특별관리리스트 조회) */ C##RG.DEC_B64(T1.STDNT_FLNM_ENCPT) AS FLNM --학생성명암호화 ,T1.STDNT_BRTH_YMD AS BRDT --학생출생일자 ,T1.SCHULW_DSCNTC_CS_CN AS STDNT_THNK_DSCNTC_CS --학업중단사유내용 ,TO_CHAR(T1.FRST_REG_DT,'YYYYMMDD') AS REG_DAY --등록일시 ,(SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'MOE_OFCDC_SE_CD' AND CMMNS_CD_VALUE = T1.ENFSN_NO) AS ENFSN_NO --교육청명 ,TO_CHAR(T1.INDEX_SN) AS INDEX_SN --색인일련번호 ,T1.ULD_RQSTDO_STTS_SE_CD AS ULD_RQSTDO_STTS_SE_CD --업로드의뢰서상태구분코드 ,C##RG.DEC_B64(T1.STDNT_MBL_TELNO_ENCPT) AS STDNT_MBL_TELNO_ENCPT --학생휴대전화번호암호화 ,T1.STDNT_TELNO AS STDNT_TELNO --학생전화번호 ,C##RG.DEC_B64(T1.STDNT_EML_ADDR_ENCPT) AS STDNT_EML_ADDR_ENCPT --학생이메일주소암호화 ,T1.STTY_AGT_CTTPC_TELNO AS STTY_AGT_CTTPC_TELNO --법정대리인연락처전화번호 ,C##RG.DEC_B64(T1.STTY_AGT_EML_ADDR_ENCPT) AS STTY_AGT_EML_ADDR_ENCPT --법정대리인이메일주소암호화 ,T1.HNCFRT_HPE_COSE_NM AS HNCFRT_HPE_COSE_NM --향후희망진로명 FROM AKA221 T1 /* 교육청집단연계-업로드파일상세 */ WHERE 1=1
AND T1.ENFSN_NO = #{ENFSN_NO}
AND T1.ULD_RQSTDO_STTS_SE_CD = '04'
AND TO_CHAR(T1.FRST_REG_DT, 'YYYYMMDD') BETWEEN #{START_DATE} AND #{END_DATE}
AND T1.STDNT_FLNM_ENCPT = C##RG.ENC_B64(#{STDNT_FLNM})
ORDER BY T1.FRST_REG_DT DESC

SELECT /* isry.drmgs.link.OfcdcLinkAplyMapper.selectOfcdcErrorInfoList(오류정보리스트 조회) */ C##RG.DEC_B64(T1.STDNT_FLNM_ENCPT) AS FLNM --학생성명암호화 ,T1.STDNT_BRTH_YMD AS BRDT --학생출생일자 ,T1.SCHULW_DSCNTC_CS_CN AS STDNT_THNK_DSCNTC_CS --학업중단사유내용 ,TO_CHAR(T1.FRST_REG_DT,'YYYYMMDD') AS REG_DAY --등록일시 ,(SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'MOE_OFCDC_SE_CD' AND CMMNS_CD_VALUE = T1.ENFSN_NO) AS ENFSN_NO --교육청명 ,TO_CHAR(T1.INDEX_SN) AS INDEX_SN --색인일련번호 ,T1.ULD_RQSTDO_STTS_SE_CD AS ULD_RQSTDO_STTS_SE_CD --업로드의뢰서상태구분코드 ,C##RG.DEC_B64(T1.STDNT_MBL_TELNO_ENCPT) AS STDNT_MBL_TELNO_ENCPT --학생휴대전화번호암호화 ,T1.STDNT_TELNO AS STDNT_TELNO --학생전화번호 ,C##RG.DEC_B64(T1.STDNT_EML_ADDR_ENCPT) AS STDNT_EML_ADDR_ENCPT --학생이메일주소암호화 ,T1.STTY_AGT_CTTPC_TELNO AS STTY_AGT_CTTPC_TELNO --법정대리인연락처전화번호 ,C##RG.DEC_B64(T1.STTY_AGT_EML_ADDR_ENCPT) AS STTY_AGT_EML_ADDR_ENCPT --법정대리인이메일주소암호화 ,T1.HNCFRT_HPE_COSE_NM AS HNCFRT_HPE_COSE_NM --향후희망진로명 ,T1.ERR_INFO_DTL_CN AS ERR_INFO_DTL_CN --오류정보상세내용 FROM AKA221 T1 /* 교육청집단연계-업로드파일상세 */ WHERE 1=1
AND T1.ENFSN_NO = #{ENFSN_NO}
AND T1.ULD_RQSTDO_STTS_SE_CD = '03'
AND TO_CHAR(T1.FRST_REG_DT, 'YYYYMMDD') BETWEEN #{START_DATE} AND #{END_DATE}
AND T1.STDNT_FLNM_ENCPT = C##RG.ENC_B64(#{STDNT_FLNM})
ORDER BY T1.FRST_REG_DT DESC

