SELECT /* isry.drmgs.link.OfcdcLinkAplyMapper.selectInstEnfsnNo(기관번호,담당자종사자번호 구하기) */ NVL(T1.INST_NO,'0') AS INST_NO --기관번호 ,NVL(T1.PIC_ENFSN_NO,'0') AS PIC_ENFSN_NO --담당자종사자번호 ,T1.SGG_CD AS SGG_CD --시군구코드 FROM SAA000 T1 /* 통합기관 */ WHERE 1=1 AND T1.UNT_TASKWK_SE_CD = 'U03' AND T1.INST_TYPE_SE_CD = '8' AND (T1.INST_NM LIKE '%꿈드림%' OR T1.INST_NM LIKE '%학교밖%') AND T1.SGG_CD = (SELECT X.SGG_CD FROM SAA020 X/* 시군구코드 */ WHERE 1=1 AND X.CTPV_NM = #{CTPV_NM}
AND X.SGG_NM = #{SGG_NM}
) UNION ALL
SELECT NVL(T1.INST_NO,'0') AS INST_NO --기관번호 ,NVL(T1.PIC_ENFSN_NO,'0') AS PIC_ENFSN_NO --담당자종사자번호 ,T1.SGG_CD AS SGG_CD --시군구코드 FROM SAA000 T1 /* 통합기관 */ WHERE 1=1 AND T1.UNT_TASKWK_SE_CD = 'U03' AND T1.INST_TYPE_SE_CD = '8' AND (T1.INST_NM LIKE '%꿈드림%' OR T1.INST_NM LIKE '%학교밖%') AND T1.SGG_CD = (SELECT X.SGG_CD FROM SAA020 X/* 시군구코드 */ WHERE 1=1 AND X.CTPV_NM = #{CTPV_NM}
AND X.SGG_NM = #{SGG_NM1}
) UNION ALL
SELECT NVL(T1.INST_NO,'0') AS INST_NO --기관번호 ,NVL(T1.PIC_ENFSN_NO,'0') AS PIC_ENFSN_NO --담당자종사자번호 ,T1.SGG_CD AS SGG_CD --시군구코드 FROM SAA000 T1 /* 통합기관 */ WHERE 1=1 AND T1.UNT_TASKWK_SE_CD = 'U03' AND (T1.INST_NM LIKE '%꿈드림%' OR T1.INST_NM LIKE '%학교밖%') AND T1.CTPV_CD = #{CTPV_SE_CD} AND INST_TYPE_SE_CD = '5'

